    async Task Run(string title,Func<Task> work){if(busy)return;busy=true;SetStatus(title,"Подготовка и проверка файлов. Это может занять некоторое время.",0);progress.Visible=true;check.Enabled=sync.Enabled=rollback.Enabled=browse.Enabled=folder.Enabled=experimental.Enabled=updateLauncher.Enabled=false;play.Enabled=false;try{await work();}catch(Exception ex){Fail(ex);}finally{busy=false;progress.Visible=false;check.Enabled=sync.Enabled=rollback.Enabled=browse.Enabled=folder.Enabled=experimental.Enabled=updateLauncher.Enabled=true;if(closingForUpdate)Close();}}
    protected override void WndProc(ref Message m){const int hit=0x84;if(m.Msg==hit&&WindowState==FormWindowState.Normal){Point p=PointToClient(new Point(unchecked((short)(long)m.LParam),unchecked((short)((long)m.LParam>>16))));int edge=7;bool left=p.X<edge,right=p.X>=Width-edge,top=p.Y<edge,bottom=p.Y>=Height-edge;int value=top?(left?13:right?14:12):bottom?(left?16:right?17:15):left?10:right?11:0;if(value!=0){m.Result=new IntPtr(value);return;}}base.WndProc(ref m);}
